} else {
  // Product-level snapshot: NULL variant — use manual upsert
  const [existingSnapNull] = await sql<{ id: string }[]>`
    SELECT id FROM dashboard_snapshots
    WHERE product_external_id = ${productIdStr}::bigint
    AND variant_external_id IS NULL
    LIMIT 1
  `;
  if (existingSnapNull) {
    await sql`
      UPDATE dashboard_snapshots
      SET active_waitlist_count = ${activeCount},
          total_signups = ${totalSignups},
          total_notified = ${totalNotified},
          total_conversions = ${totalConversions},
          last_restock_at = now(),
          snapshot_updated_at = now()
      WHERE id = ${existingSnapNull.id}
    `;
  } else {
    await sql`
      INSERT INTO dashboard_snapshots (
        product_external_id, variant_external_id, item_display_name,
        active_waitlist_count, total_signups, total_notified, total_conversions,
        last_restock_at, snapshot_updated_at
      ) VALUES (
        ${productIdStr}::bigint, NULL, ${displayName},
        ${activeCount}, ${totalSignups}, ${totalNotified}, ${totalConversions},
        now(), now()
      )
    `;
  }
}
